import sys
sys.setrecursionlimit(200000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        V = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(V)]

    for i in range(V):
        try:
            count = int(next(iterator))
            for _ in range(count):
                neighbor = int(next(iterator))
                adj[i].append(neighbor)
        except StopIteration:
            break

    tin = [-1] * V
    low = [-1] * V
    visited = [False] * V
    ap = set()
    timer = [0]

    def dfs(u, p=-1):
        visited[u] = True
        tin[u] = low[u] = timer[0]
        timer[0] += 1
        children = 0

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                low[u] = min(low[u], tin[v])
            else:
                children += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if p != -1 and low[v] >= tin[u]:
                    ap.add(u)

        if p == -1 and children > 1:
            ap.add(u)

    for i in range(V):
        if not visited[i]:
            dfs(i)

    if not ap:
        print("-1")
    else:
        result = sorted(list(ap))
        print(result)

if __name__ == "__main__":
    main()
